R = []
R.append((7644476,
("Risotto de cebada y hongos silvestres",
 "Un risotto cremoso, preparado con cebada en lugar de arroz y cubierto con una variedad de hongos.",
 ["2 cucharaditas de aceite de oliva", "400 g de hongos variados, en rebanadas", "1 cebolla (140 g), picada", "1 pimiento rojo (160 g), picado", "250 g de cebada perlada", "2 dientes de ajo, machacados", "1 cucharadita colmada de orégano seco", "2 buenas pizcas de pimienta blanca", "1 cubito de caldo de verduras bajo en sal en 700 ml de agua hirviendo", "1 cucharada colmada de albahaca fresca picada, y más para servir", "4 cucharadas de sustituto de crema a base de avena o soya", "un buen molido de pimienta negra"],
 ["Caliente el aceite en una sartén grande antiadherente, añada la cebolla y cocine 1 minuto.", "Añada el pimiento rojo y el ajo y cocine 2 minutos; luego añada los hongos y cocine de 2 a 3 minutos.", "Reserve unos cuantos hongos para decorar el plato.", "Incorpore la cebada, añada el caldo, el orégano y la pimienta, y mezcle bien. Deje que hierva, luego baje el fuego, tape y cocine a fuego lento, revolviendo con frecuencia.", "Después de unos 25 minutos, destape y siga cocinando a fuego lento unos 10 minutos, hasta que el líquido se absorba y se evapore el exceso.", "La cebada debe quedar cocida pero todavía firme (\"al dente\").", "Incorpore el sustituto de crema y la albahaca fresca; luego sirva con pimienta negra recién molida, espolvoreado con la albahaca y los hongos reservados."],
 ["Sirve cualquier tipo de hongos para este plato, pero lo ideal es una combinación de distintos tipos. Puede comprar paquetes de hongos silvestres variados en la mayoría de los supermercados y completarlos con un paquete de hongos comunes.", "Se puede congelar una vez cocido. Enfríe rápidamente. Descongele en el refrigerador y recaliente bien hasta que esté muy caliente por completo."]),
("ريزوتو الشعير بالفطر البري",
 "ريزوتو كريمي مصنوع من الشعير بدلًا من الأرز ومزين بأنواع متنوعة من الفطر.",
 ["2 ملعقة صغيرة من زيت الزيتون", "400 غرام من الفطر المشكل، مقطعًا شرائح", "1 بصلة (140 غرامًا)، مفرومة", "1 حبة فلفل رومي أحمر (160 غرامًا)، مفرومة", "250 غرامًا من الشعير المقشور (اللؤلؤي)", "2 فص ثوم، مهروسة", "1 ملعقة صغيرة مكدسة من الأوريغانو المجفف", "2 رشة كبيرة من الفلفل الأبيض", "1 مكعب مرق خضار قليل الملح في 700 مل من الماء المغلي", "1 ملعقة كبيرة مكدسة من الريحان الطازج المفروم، والمزيد للتقديم", "4 ملاعق كبيرة من بديل الكريمة المصنوع من الشوفان أو الصويا", "رشة كبيرة من الفلفل الأسود المطحون"],
 ["سخّن الزيت في مقلاة كبيرة غير لاصقة، وأضف البصل واطهه دقيقة واحدة.", "أضف الفلفل الرومي الأحمر والثوم واطههما دقيقتين، ثم أضف الفطر واطهه من 2 إلى 3 دقائق.", "احتفظ ببعض حبات الفطر جانبًا لتزيين الطبق.", "أضف الشعير وصبّ المرق والأوريغانو والفلفل ثم اخلط جيدًا. اتركه حتى يغلي ثم خفّف النار وغطِّ القدر واتركه على نار هادئة مع التحريك بانتظام.", "بعد حوالي 25 دقيقة، ارفع الغطاء وواصل الطهي على نار هادئة نحو 10 دقائق حتى يُمتص السائل ويتبخر الزائد منه.", "يجب أن يكون الشعير ناضجًا لكنه ما زال متماسكًا (\"آل دنتي\").", "قلّب بديل الكريمة والريحان الطازج، ثم قدّمه مع الفلفل الأسود المطحون طازجًا، ورشّ عليه الريحان والفطر المحفوظ جانبًا."],
 ["يصلح أي نوع من الفطر لهذا الطبق، لكن الأفضل مزيج من أنواع مختلفة. يمكنك شراء عبوات فطر بري مشكل من معظم المتاجر الكبرى، ثم زيادة الكمية بعبوة فطر عادي.", "يصلح للتجميد بعد الطهي. برّده بسرعة. أذبه في الثلاجة وأعد تسخينه جيدًا حتى يسخن تمامًا من الداخل."])))
R.append((7644993,
("Pastel de camote",
 "Es una receta deliciosa que queda muy bien como postre, quizás con un poco de yogur o natillas.",
 ["900 g de camotes, pelados y picados", "25 g de mantequilla", "100 g de azúcar morena suave oscura", "ralladura y jugo de 1 lima", "4 huevos", "4 cucharadas de leche descremada", "½ cucharadita de canela molida", "½ cucharadita de nuez moscada molida", "2 cucharaditas de polvo para hornear", "75 g de pasas"],
 ["Precaliente el horno a 180 ºC (gas 4). Ponga los camotes en una olla grande, cubra con agua y cocine de 20 a 25 minutos, hasta que estén tiernos. Escurra y haga puré; deje enfriar un poco y luego incorpore la mantequilla, el azúcar y la ralladura y el jugo de lima.", "En un recipiente aparte, bata el resto de los ingredientes e incorpórelos a la mezcla de camote.", "Engrase y forre un molde para pan de 900 g (18 cm x 8 cm de profundidad). Vierta la mezcla en el molde y hornee aproximadamente de 1½ a 1¾ horas, hasta que esté firme.", "Compruebe la firmeza insertando un palillo largo; debe salir limpio cuando el pastel esté cocido."],
 ["También puede poner la mezcla en moldecitos o platos individuales y hornear unos 45 minutos.", "Se conserva en el refrigerador hasta por 5 días. Caliente una rebanada y sírvala con crème fraîche reducida en grasa o yogur.", "Si no desea usar ron, utilice 3 cucharadas de jugo de limón en su lugar."]),
("كعكة بودينغ البطاطا الحلوة",
 "وصفة لذيذة تُقدَّم رائعة كحلوى، ربما مع قليل من الزبادي أو الكاسترد.",
 ["900 غرام من البطاطا الحلوة، مقشرة ومقطعة", "25 غرامًا من الزبدة", "100 غرام من السكر البني الداكن الطري", "قشر وعصير 1 ليمونة خضراء مبشورة", "4 بيضات", "4 ملاعق كبيرة من الحليب منزوع الدسم", "نصف ملعقة صغيرة من القرفة المطحونة", "نصف ملعقة صغيرة من جوزة الطيب المطحونة", "2 ملعقة صغيرة من البيكنج باودر", "75 غرامًا من الزبيب"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). ضع البطاطا الحلوة في قدر كبير، وغطِّها بالماء واطهها من 20 إلى 25 دقيقة حتى تلين. صفِّها واهرسها جيدًا، واتركها تبرد قليلًا ثم أضف الزبدة والسكر وقشر الليمون الأخضر وعصيره وقلّب.", "في وعاء منفصل، اخفق باقي المكونات معًا، ثم أضفها إلى خليط البطاطا الحلوة وقلّب.", "ادهن قالب خبز (قالب رغيف) سعة 900 غرام (18 سم × 8 سم عمقًا) وبطّنه بالورق. اسكب الخليط في القالب واخبزه حوالي 1½ إلى 1¾ ساعة حتى يتماسك.", "افحص التماسك بغرز سيخ فيه، ويجب أن يخرج نظيفًا عند نضج الطبق."],
 ["يمكنك أيضًا وضع الخليط في أوعية فردية صغيرة وخبزه نحو 45 دقيقة.", "يُحفظ في الثلاجة حتى 5 أيام. سخّن شريحة وقدّمها مع كريمة حامضة (كريم فريش) قليلة الدسم أو زبادي.", "إذا كنت لا تريد استخدام الرم، فاستخدم 3 ملاعق كبيرة من عصير الليمون بدلًا منه."])))
R.append((7649613,
("Pastel de frutas rico",
 "Perfecto con una taza de té, este pastel de frutas rico está lleno de sabor y es un excelente antojo para la tarde.",
 ["75 g de pasas sultanas", "100 g de pasas", "25 g de cáscara de cítricos confitada", "100 ml de agua hirviendo", "1 plátano mediano, hecho puré", "2 huevos, batidos", "75 ml de aceite de colza", "1 calabacín mediano, rallado (200 g)", "1 manzana, rallada", "1 zanahoria, rallada fina", "150 g de harina integral", "1 cucharadita de polvo para hornear", "3 cucharaditas de mezcla de especias molidas", "6 cerezas confitadas, partidas por la mitad", "20 g de almendras enteras, peladas"],
 ["Precaliente el horno a 170 °C (gas 3). Ponga las pasas sultanas, las pasas y la cáscara confitada en un tazón, cubra con el agua hirviendo y reserve.", "Mezcle el plátano en puré, los huevos y el aceite en un tazón grande y bata bien.", "Incorpore el calabacín, la manzana y la zanahoria; luego añada la harina, el polvo para hornear y la mezcla de especias. Después añada la fruta seca junto con el agua del remojo.", "Mezcle bien y vierta en un molde para pastel de 20 cm forrado con papel pergamino; cubra con las cerezas y las almendras. Tape con papel de aluminio y hornee 1½ horas. Retire el papel de aluminio de 15 a 20 minutos antes de que termine el tiempo de cocción y hornee el tiempo restante.", "Compruebe con un palillo largo o un cuchillo, que debe salir limpio cuando el pastel esté cocido, y retire del horno."],
 ["Fácilmente puede preparar este pastel con harina sin gluten, pero quizá necesite añadir 50 ml más de líquido, según el tipo de harina que elija.", "Cualquier fruta seca queda bien: ciruelas pasas, albaricoques (chabacanos), pasas de Corinto o fruta mixta.", "Una vez cocido, si lo prefiere, puede rociarlo con 1 cucharadita de miel líquida."]),
("كعكة الفاكهة الغنية",
 "مثالية مع كوب من الشاي، وهذه الكعكة الغنية بالفاكهة مليئة بالنكهة وهي حلوى مثالية لوقت العصر.",
 ["75 غرامًا من الزبيب السلطاني", "100 غرام من الزبيب", "25 غرامًا من قشور الحمضيات المسكّرة", "100 مل من الماء المغلي", "1 موزة متوسطة، مهروسة", "2 بيضة، مخفوقة", "75 مل من زيت اللفت (الكانولا)", "1 كوسا متوسطة، مبشورة (200 غرام)", "1 تفاحة، مبشورة", "1 جزرة، مبشورة ناعمًا", "150 غرامًا من دقيق القمح الكامل", "1 ملعقة صغيرة من البيكنج باودر", "3 ملاعق صغيرة من خليط البهارات المطحونة", "6 حبات كرز مسكّر، مقسومة إلى نصفين", "20 غرامًا من اللوز الكامل المقشر"],
 ["سخّن الفرن مسبقًا إلى 170° مئوية (علامة الغاز 3). ضع الزبيب السلطاني والزبيب والقشور المسكّرة في وعاء، وغطِّها بالماء المغلي واتركها جانبًا.", "اخلط الموز المهروس والبيض والزيت في وعاء كبير واخفق جيدًا.", "أضف الكوسا والتفاح والجزر وقلّب، ثم أضف الدقيق والبيكنج باودر وخليط البهارات وقلّب. بعد ذلك أضف الفاكهة المجففة مع ماء النقع.", "اخلط جيدًا وضع الخليط في قالب كعك قطره 20 سم مبطّن بورق الخبز، وزيّنه بالكرز واللوز. غطِّه بورق الألمنيوم واخبزه في الفرن 1½ ساعة. أزل ورق الألمنيوم قبل نهاية وقت الخبز بـ 15 إلى 20 دقيقة، ثم أكمل الخبز للوقت المتبقي.", "افحصه بسيخ أو سكين، ويجب أن يخرج نظيفًا عند النضج، ثم أخرجه من الفرن."],
 ["يمكنك بسهولة تحضير هذه الكعكة بدقيق خالٍ من الغلوتين، لكنك قد تحتاج إلى إضافة 50 مل إضافية من السائل حسب نوع الدقيق الذي تختاره.", "يصلح أي نوع من الفاكهة المجففة: الخوخ المجفف أو المشمش أو الزبيب الصغير (الكشمش) أو الفاكهة المشكلة.", "بعد الخبز، يمكنك رش 1 ملعقة صغيرة من العسل السائل فوقها إن رغبت."])))
R.append((7651076,
("Arroz jollof con pollo",
 "Un popular plato de África Occidental que se cocina en una sola olla, por lo que es ideal para una cena sencilla y sabrosa entre semana.",
 ["2 cucharaditas de aceite de colza", "1 cebolla grande (170 g), picada", "350 g de pechuga de pollo sin piel y sin hueso, cortada en trozos", "1 pimiento rojo grande (170 g), picado", "1 pimiento amarillo grande (170 g), picado", "2 dientes de ajo, machacados", "3 cm de raíz de jengibre fresco, finamente picada", "de medio a 1 chile Scotch Bonnet, picado", "2 cucharadas de puré de tomate", "200 g de arroz basmati integral, enjuagado con agua fría", "1 cubito de caldo de pollo reducido en sal disuelto en 450 ml de agua", "1 lata de 400 g de tomates picados", "100 g de okra, cortada en trozos de 2 cm", "2 cucharadas de cilantro picado grueso"],
 ["Caliente el aceite en una olla grande, añada la cebolla y cocine de 3 a 4 minutos, hasta que empiece a dorarse.", "Añada los trozos de pollo y cocine de 3 a 4 minutos más, revolviendo con frecuencia para que el pollo se cocine de manera uniforme.", "Añada los pimientos rojo y amarillo y revuelva 2 minutos más; luego añada el ajo, el jengibre, el chile y el puré de tomate, y mezcle bien.", "Ahora añada el arroz y mezcle de nuevo, revolviendo durante un minuto para que todo el arroz quede cubierto con la mezcla de puré de tomate.", "Añada el caldo y los tomates y mezcle bien; deje que hierva, luego reduzca el fuego, tape y cocine a fuego lento 8 minutos.", "Esparza la okra sobre el arroz, vuelva a tapar y cocine a fuego lento 5 minutos más.", "Ahora apague el fuego, pero no quite la tapa, y deje reposar 5 minutos. Añada el cilantro, mezcle bien y sirva."],
 ["Puede preparar este plato con cordero, res, cerdo o pavo.", "Para una versión vegetariana o vegana, pruebe a añadir trozos de calabacín, berenjena y tofu marinado en lugar del pollo, y use un cubito de caldo de verduras.", "Para una versión con mariscos, use un cubito de caldo de pescado y añada cubos de salmón o camarones junto con la okra.", "Instrucciones para congelar: Se puede congelar una vez cocido. Enfríe rápidamente. Descongele en el refrigerador y recaliente bien hasta que esté muy caliente por completo. Consuma de inmediato y deseche las sobras."]),
("أرز جولوف مع الدجاج",
 "طبق شهير من غرب أفريقيا يُطهى في قدر واحدة، فهو مثالي لعشاء بسيط ولذيذ في منتصف الأسبوع.",
 ["2 ملعقة صغيرة من زيت اللفت (الكانولا)", "1 بصلة كبيرة (170 غرامًا)، مفرومة", "350 غرامًا من صدر الدجاج بدون جلد ولا عظم، مقطعًا قطعًا", "1 حبة فلفل رومي أحمر كبيرة (170 غرامًا)، مفرومة", "1 حبة فلفل رومي أصفر كبيرة (170 غرامًا)، مفرومة", "2 فص ثوم، مهروسة", "3 سم من جذر الزنجبيل الطازج، مفرومًا ناعمًا", "من نصف إلى 1 حبة فلفل حار سكوتش بونيت، مفرومة", "2 ملعقة كبيرة من معجون الطماطم", "200 غرام من أرز بسمتي بني، مغسول بالماء البارد", "1 مكعب مرق دجاج قليل الملح مذاب في 450 مل من الماء", "1 علبة طماطم مفرومة 400 غرام", "100 غرام من البامية، مقطعة إلى قطع بطول 2 سم", "2 ملعقة كبيرة من الكزبرة الخضراء المفرومة فرمًا خشنًا"],
 ["سخّن الزيت في قدر كبيرة، ثم أضف البصل واطهه من 3 إلى 4 دقائق حتى يبدأ بالاحمرار.", "أضف قطع الدجاج واطهها من 3 إلى 4 دقائق إضافية مع التحريك بانتظام لضمان نضج الدجاج بالتساوي.", "أضف الفلفل الرومي الأحمر والأصفر وقلّب دقيقتين إضافيتين، ثم أضف الثوم والزنجبيل والفلفل الحار ومعجون الطماطم واخلط جيدًا.", "أضف الأرز الآن واخلط مرة أخرى، وقلّب لمدة دقيقة حتى يتغطى كل الأرز بخليط معجون الطماطم.", "أضف المرق والطماطم واخلط جيدًا، واتركه حتى يغلي ثم خفّف النار وغطِّ القدر واتركه على نار هادئة 8 دقائق.", "انثر البامية فوق الأرز، وأعد الغطاء واتركه على نار هادئة 5 دقائق أخرى.", "أطفئ النار الآن دون رفع الغطاء واتركه يستريح 5 دقائق. أضف الكزبرة الخضراء واخلط جيدًا وقدّم."],
 ["يمكنك تحضير هذا الطبق بلحم الضأن أو البقر أو الخنزير أو الديك الرومي.", "للحصول على نسخة نباتية، جرّب إضافة قطع من الكوسا والباذنجان والتوفو المتبّل بدلًا من الدجاج، واستخدم مكعب مرق خضار.", "للحصول على نسخة بالمأكولات البحرية، استخدم مكعب مرق سمك وأضف مكعبات سلمون أو بعض الروبيان مع البامية.", "تعليمات التجميد: يصلح للتجميد بعد الطهي. برّده بسرعة. أذبه في الثلاجة وأعد تسخينه جيدًا حتى يسخن تمامًا من الداخل. تناوله فورًا وتخلّص من أي بقايا."])))
R.append((7652430,
("Crumble de manzana, zarzamora, avena y semillas",
 "Este crumble bajo en grasa es rápido y fácil de preparar.",
 ["100 g de pan rallado integral fresco", "50 g de avena en hojuelas", "1 cucharada de semillas de calabaza", "2 manzanas de mesa", "150 g de zarzamoras", "50 ml de jugo de manzana", "1 cucharada de miel líquida", "crème fraîche semidescremada o yogur natural, para servir"],
 ["Precaliente el horno a 180 °C (gas 4). Ponga el pan rallado, la avena y las semillas de calabaza en un tazón y mezcle bien.", "Quite el corazón a las manzanas y píquelas, dejándoles la cáscara, y colóquelas en un molde apto para horno. Añada las zarzamoras y luego vierta el jugo de manzana en el molde.", "Espolvoree la mezcla del crumble sobre la fruta y luego rocíe con la miel.", "Hornee unos 15 a 20 minutos, hasta que esté dorado.", "Sirva el crumble de inmediato, con una bola de crème fraîche semidescremada o yogur natural."],
 ["Al usar manzanas de mesa en esta receta, en lugar de las variedades para cocinar, no necesita añadir azúcar adicional, porque las manzanas de mesa son naturalmente más dulces.", "La cáscara de la manzana contiene fibra, así que evite pelarlas.", "Las zarzamoras están llenas de antioxidantes, incluida la vitamina C, y también son una buena fuente de fibra.", "Los cereales integrales, como la avena, contienen un tipo de fibra llamada betaglucano que puede ayudar a reducir el colesterol si se consume con regularidad."]),
("كرامبل التفاح والتوت الأسود والشوفان والبذور",
 "هذا الكرامبل قليل الدسم سريع وسهل التحضير.",
 ["100 غرام من فتات خبز القمح الكامل الطازج", "50 غرامًا من رقائق الشوفان", "1 ملعقة كبيرة من بذور القرع", "2 تفاحة للأكل", "150 غرامًا من التوت الأسود", "50 مل من عصير التفاح", "1 ملعقة كبيرة من العسل السائل", "كريمة حامضة (كريم فريش) نصف دسمة أو زبادي طبيعي، للتقديم"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). ضع فتات الخبز والشوفان وبذور القرع في وعاء واخلطها جيدًا.", "انزع قلب التفاح وقطّعه مع إبقاء القشر، وضعه في طبق يتحمل حرارة الفرن. أضف التوت الأسود ثم اسكب عصير التفاح في الطبق.", "انثر خليط الكرامبل فوق الفاكهة، ثم رشّ العسل فوقه.", "اخبزه في الفرن نحو 15 إلى 20 دقيقة حتى يصبح ذهبي اللون.", "قدّم الكرامبل فورًا مع مغرفة من الكريمة الحامضة نصف الدسمة أو الزبادي الطبيعي."],
 ["باستخدام تفاح الأكل في هذه الوصفة بدلًا من تفاح الطهي، لا تحتاج إلى إضافة أي سكر إضافي، لأن تفاح الأكل أحلى بطبيعته.", "تحتوي قشور التفاح على الألياف، لذا تجنب تقشيرها.", "التوت الأسود مليء بمضادات الأكسدة، بما في ذلك فيتامين C، كما أنه مصدر جيد للألياف.", "تحتوي الحبوب الكاملة، مثل الشوفان، على نوع من الألياف يسمى بيتا غلوكان، يمكن أن يساعد في خفض الكوليسترول عند تناوله بانتظام."])))
R.append((7654528,
("Ensalada vietnamita crujiente de cacahuate",
 "Una ensalada de fideos llena de verduras, ideal para un almuerzo para llevar.",
 ["150 g de fideos de huevo secos", "2 cucharaditas de aceite de ajonjolí tostado", "1 cucharadita de aceite de colza", "1 pimiento rojo, cortado en tiras finas", "4 cm de raíz de jengibre fresco, finamente picada", "un cuarto de chile rojo pequeño, finamente picado (opcional)", "4 cebollas verdes, limpias y picadas", "150 g de brotes de soya", "un puñado de hojas de cilantro, recién picadas", "5 cm de pepino, picado en trozos pequeños", "jugo de media lima", "30 g de cacahuates naturales sin sal, picados grueso", "2 cucharaditas de salsa de soya reducida en sal, si lo desea"],
 ["Cocine los fideos según las instrucciones del paquete (los tiempos varían; por lo general de 4 a 6 minutos), escurra e introdúzcalos de inmediato en agua fría para detener la cocción. Escurra de nuevo, póngalos en un tazón con el aceite de ajonjolí tostado, mezcle bien y reserve.", "Mientras tanto, ponga el aceite de colza en una sartén y añada el pimiento rojo, el jengibre y el chile (si lo usa) y revuelva 2 minutos.", "Luego añada las cebollas verdes y los brotes de soya, mezcle 1 minuto y retire del fuego.", "Añada la mezcla de brotes de soya a los fideos, junto con el cilantro, el pepino, el jugo de lima y la mitad de los cacahuates, y mezcle bien.", "Reparta en recipientes para el almuerzo y espolvoree el resto de los cacahuates por encima; añada 1 cucharadita de salsa de soya a cada uno para dar sabor, si lo desea."],
 ["Elija salsa de soya reducida en sal para disminuir el contenido de sal de esta receta. También puede omitir por completo este ingrediente para que la receta sea más saludable.", "Use fideos de arroz y tamari sin gluten, en lugar de salsa de soya, si la usa, para una ensalada sin gluten.", "También puede probar esta receta con una mezcla de nueces, semillas de girasol y semillas de calabaza."]),
("سلطة فيتنامية مقرمشة بالفول السوداني",
 "سلطة نودلز مليئة بالخضار، رائعة لوجبة غداء سريعة.",
 ["150 غرامًا من نودلز البيض المجففة", "2 ملعقة صغيرة من زيت السمسم المحمص", "1 ملعقة صغيرة من زيت اللفت (الكانولا)", "1 حبة فلفل رومي أحمر، مقطعة أعوادًا رفيعة", "4 سم من جذر الزنجبيل الطازج، مفرومًا ناعمًا", "ربع حبة فلفل حار أحمر صغيرة، مفرومة ناعمًا (اختياري)", "4 حبات بصل أخضر، منظّفة ومفرومة", "150 غرامًا من نبتة الفاصولياء (براعم الفول)", "حفنة من أوراق الكزبرة الخضراء، مفرومة طازجة", "5 سم من الخيار، مقطعًا قطعًا صغيرة", "عصير نصف ليمونة خضراء", "30 غرامًا من الفول السوداني الطبيعي غير المملح، مفرومًا فرمًا خشنًا", "2 ملعقة صغيرة من صلصة الصويا قليلة الملح، إن رغبت"],
 ["اسلق النودلز حسب تعليمات العبوة (تختلف المدة، وهي عادةً من 4 إلى 6 دقائق)، وصفِّها وضعها فورًا في ماء بارد لإيقاف النضج. صفِّها مرة أخرى ثم ضعها في وعاء مع زيت السمسم المحمص واخلط جيدًا واتركها جانبًا.", "في الأثناء، ضع زيت اللفت (الكانولا) في مقلاة، ثم أضف الفلفل الرومي الأحمر والزنجبيل والفلفل الحار (إن استخدمته) وقلّب دقيقتين.", "بعد ذلك أضف البصل الأخضر ونبتة الفاصولياء وقلّب دقيقة واحدة ثم ارفعه عن النار.", "أضف خليط نبتة الفاصولياء إلى النودلز مع الكزبرة الخضراء والخيار وعصير الليمون الأخضر ونصف كمية الفول السوداني، واخلط جيدًا.", "وزّعها في علب الغداء ورشّ بقية الفول السوداني فوقها، وأضف 1 ملعقة صغيرة من صلصة الصويا إلى كل علبة لإضفاء النكهة إن رغبت."],
 ["اختر صلصة صويا قليلة الملح لتقليل محتوى الملح في هذه الوصفة. أو يمكنك حذف هذا المكون تمامًا لجعل الوصفة أكثر صحة.", "استخدم نودلز الأرز وصلصة التاماري الخالية من الغلوتين بدلًا من صلصة الصويا، إن استخدمتها، للحصول على سلطة خالية من الغلوتين.", "يمكنك أيضًا تجربة هذه الوصفة مع خليط من الجوز وبذور عباد الشمس وبذور القرع."])))
R.append((7658821,
("Sopa de coliflor y puerro",
 "Una sopa contundente y reconfortante, rápida y económica de preparar. Con crutones de coliflor tostados y picantes, es una comida sabrosa.",
 ["2 cucharaditas de aceite de colza + 1 cucharadita para engrasar la bandeja", "1 coliflor (800 g), en floretes", "1 cucharadita colmada de cúrcuma", "1 cebolla grande, picada", "2 puerros, en rodajas", "1 cucharadita de comino molido", "2 dientes de ajo, machacados", "una buena pizca de pimienta blanca", "1 cubito de caldo de verduras bajo en sal en 600 ml de agua", "1 lata de 400 g de frijoles blancos grandes (butter beans), escurridos (240 g)", "300 ml de leche descremada", "Pimienta negra al gusto"],
 ["Precaliente el horno a 180 °C (gas 4) y engrase ligeramente una bandeja para hornear.", "Separe ¼ de la coliflor en floretes muy pequeños, enjuague con agua fría, sacuda el exceso y póngalos en un tazón. Espolvoree con la cúrcuma y mezcle bien. Colóquelos en la bandeja para hornear y ase de 10 a 15 minutos, hasta que los bordes empiecen a chamuscarse; luego reserve.", "Mientras tanto, ponga 2 cucharaditas de aceite en una olla y añada la cebolla. Cocine de 3 a 4 minutos hasta que se ablande, sin dorarla. Añada los puerros y el resto de la coliflor y cocine de 3 a 4 minutos más, revolviendo con frecuencia.", "Añada el comino, el ajo, la pimienta y el caldo y deje que hierva. Baje el fuego, tape y cocine suavemente de 8 a 10 minutos, hasta que la coliflor esté cocida.", "Añada los frijoles blancos y licue poco a poco, añadiendo la leche hasta que quede suave. Caliente y reparta en 6 tazones; cubra con la coliflor asada y un buen molido de pimienta negra."],
 ["Puede probar con otros frijoles, como los flageolet, para esta sopa.", "Pruebe a añadir de 1 a 2 cucharaditas de pasta o polvo de curry a la sopa junto con el ajo y el comino.", "Puede preparar la sopa con anticipación y recalentarla; no coloque los crutones de coliflor sobre el plato hasta justo antes de servir.", "Instrucciones para congelar: Se puede congelar una vez cocida. Congele los crutones de coliflor por separado. Descongele en el microondas o a fuego muy bajo hasta que esté muy caliente."]),
("شوربة القرنبيط والكراث",
 "شوربة مشبعة ودافئة سريعة التحضير ورخيصة. ومع مكعبات القرنبيط المحمصة والحارة التي تشبه الكروتون، تصبح وجبة لذيذة.",
 ["2 ملعقة صغيرة من زيت اللفت (الكانولا) + 1 ملعقة صغيرة لدهن الصينية", "1 رأس قرنبيط (800 غرام)، مقطعة زهيرات", "1 ملعقة صغيرة مكدسة من الكركم", "1 بصلة كبيرة، مفرومة", "2 كراث، مقطعة شرائح", "1 ملعقة صغيرة من الكمون المطحون", "2 فص ثوم، مهروسة", "رشة كبيرة من الفلفل الأبيض", "1 مكعب مرق خضار قليل الملح في 600 مل من الماء", "1 علبة فاصوليا بيضاء كبيرة (بتر بينز) 400 غرام، مصفّاة (240 غرامًا)", "300 مل من الحليب منزوع الدسم", "فلفل أسود حسب الرغبة"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4) وادهن صينية خبز بقليل من الزيت.", "قسّم ¼ القرنبيط إلى زهيرات صغيرة جدًا، واشطفها بالماء البارد، وانفض الماء الزائد وضعها في وعاء. رشّ عليها الكركم واخلط جيدًا. ضعها على صينية الخبز وحمّصها من 10 إلى 15 دقيقة حتى تبدأ الحواف بالاسمرار، ثم ضعها جانبًا.", "في الأثناء، ضع 2 ملعقة صغيرة من الزيت في قدر وأضف البصل. اطهه من 3 إلى 4 دقائق حتى يلين دون أن يحمرّ. أضف الكراث وبقية القرنبيط واطهها من 3 إلى 4 دقائق إضافية مع التحريك بانتظام.", "أضف الكمون والثوم والفلفل والمرق واتركها حتى تغلي. خفّف النار وغطِّ القدر واتركها على نار هادئة برفق من 8 إلى 10 دقائق حتى ينضج القرنبيط.", "أضف الفاصوليا البيضاء وامزج تدريجيًا مع إضافة الحليب حتى يصبح ناعمًا. سخّنها ثم وزّعها على 6 أوعية وزيّنها بالقرنبيط المحمص ورشة كبيرة من الفلفل الأسود المطحون."],
 ["يمكنك تجربة أنواع أخرى من الفاصوليا، مثل فاصوليا فلاجوليه، لهذه الشوربة.", "جرّب إضافة 1 إلى 2 ملعقة صغيرة من معجون أو مسحوق الكاري إلى الشوربة مع الثوم والكمون.", "يمكنك تحضير الشوربة مسبقًا وإعادة تسخينها، ولا تضف مكعبات القرنبيط المحمصة فوق الطبق إلا قبل التقديم مباشرة.", "تعليمات التجميد: تصلح للتجميد بعد الطهي. جمّد مكعبات القرنبيط المحمصة بشكل منفصل. أذبها في المايكرويف أو على نار هادئة جدًا حتى تسخن تمامًا."])))
R.append((7659110,
("Panqueques de 2 ingredientes",
 "Solo necesita dos ingredientes principales para este desayuno rapidísimo.",
 ["2 plátanos, hechos puré", "1 huevo, ligeramente batido", "Aceite en aerosol para cocinar, bajo en calorías", "2 cucharadas de yogur griego natural sin grasa (0 %) y frutas del bosque frescas, para servir", "1 cucharadita de miel de agave (opcional)"],
 ["Mezcle los plátanos y el huevo con una pizca de sal.", "Rocíe una sartén con aceite en aerosol y caliéntela. Vierta un cucharón de la mezcla en la sartén y cocine 2 minutos por cada lado, hasta que esté dorado. Repita.", "Sirva cada panqueque cubierto con yogur, frutas del bosque frescas y miel de agave."],
 ["Puede probar cualquiera de sus frutas favoritas como cobertura, o incluso su crema de nueces favorita."]),
("فطائر (بان كيك) من مكونين",
 "تحتاج إلى مكونين أساسيين فقط لهذا الفطور السريع جدًا.",
 ["2 موزة، مهروسة", "1 بيضة، مخفوقة قليلًا", "بخاخ طهي منخفض السعرات", "2 ملعقة كبيرة من الزبادي اليوناني الطبيعي خالي الدسم (0%) والتوت الطازج، للتقديم", "1 ملعقة صغيرة من شراب الأغاف (اختياري)"],
 ["اخلط الموز والبيض مع رشة ملح.", "رشّ مقلاة برذاذ الطهي وسخّنها. اسكب مغرفة من الخليط في المقلاة واطهه دقيقتين على كل جانب حتى يصبح ذهبي اللون. كرر العملية.", "قدّم كل فطيرة مع الزبادي والتوت الطازج وشراب الأغاف."],
 ["يمكنك تجربة أي من فواكهك المفضلة كإضافة، أو حتى زبدة المكسرات المفضلة لديك."])))
R.append((7659367,
("Chips de verduras caseras",
 "Cree sus combinaciones de sabores favoritas con estas chips de verduras caseras, bajas en grasa y sin sal añadida.",
 ["120 g de camote", "120 g de zanahoria", "100 g de chirivía", "100 g de betabel", "15 rociadas de aceite en aerosol"],
 ["Precaliente el horno a 180 °C (gas 4). Corte las verduras en rebanadas muy delgadas; una mandolina es perfecta.", "Rocíe un poco de aceite sobre una bandeja para hornear y acomode las rebanadas de verdura sin que se traslapen. Puede que necesite prepararlas en tandas separadas, según el tamaño de su horno.", "Cocine 20 minutos, hasta que estén ligeramente doradas. Es fundamental voltear las verduras con frecuencia durante la cocción, porque se pueden quemar con facilidad. Quizá deba retirar algunas chips antes de que se cumplan los 20 minutos, porque algunas se cocinan más rápido que otras.", "Cuando todas las chips estén listas, deje enfriar, luego mezcle y sirva."],
 ["Tenga cuidado de no quemar las verduras. Las verduras de raíz tienen mucho azúcar natural, por lo que pueden chamuscarse si el horno está demasiado caliente o si no las voltea con suficiente frecuencia durante la cocción.", "Puede cocinar las chips en el microondas a 300 W durante 10 minutos y luego 1 minuto a máxima potencia; funciona bastante bien, pero solo con tandas pequeñas.", "También se pueden cocinar en una freidora de aire hasta que estén crujientes."]),
("رقائق الخضار محلية الصنع",
 "ابتكر مزيجك المفضل من النكهات مع رقائق الخضار محلية الصنع هذه قليلة الدسم ودون ملح مضاف.",
 ["120 غرامًا من البطاطا الحلوة", "120 غرامًا من الجزر", "100 غرام من الجزر الأبيض (الباستنج)", "100 غرام من الشمندر", "15 بخة من زيت البخاخ"],
 ["سخّن الفرن مسبقًا إلى 180° مئوية (علامة الغاز 4). قطّع الخضار إلى شرائح رقيقة جدًا، والمقطّعة (الماندولين) مثالية لذلك.", "رشّ قليلًا من الزيت على صينية خبز ورتّب شرائح الخضار مع التأكد من عدم تداخلها. قد تحتاج إلى تحضيرها على دفعات منفصلة حسب حجم فرنك.", "اخبزها 20 دقيقة حتى تصبح بنية فاتحة. من الضروري تقليب الخضار باستمرار أثناء الخبز لأنها قد تحترق بسهولة. وقد تحتاج إلى إخراج بعض الرقائق قبل انقضاء الـ 20 دقيقة لأن بعضها ينضج أسرع من غيره.", "عندما تنضج جميع الرقائق، اتركها تبرد ثم اخلطها وقدّمها."],
 ["احرص على ألا تحرق الخضار. تحتوي الخضار الجذرية على الكثير من السكر الطبيعي، لذا قد تحترق إذا كان الفرن شديد الحرارة أو لم تقلّبها بما يكفي أثناء الخبز.", "يمكنك طهي الرقائق في المايكرويف على 300 واط لمدة 10 دقائق، ثم دقيقة واحدة على أعلى قدرة، وهذا ينجح جيدًا لكن مع الدفعات الصغيرة فقط.", "يمكن أيضًا طهيها في القلاية الهوائية حتى تصبح مقرمشة."])))
R.append((7660536,
("Peras escalfadas con especias",
 "Un postre bajo en calorías, lo bastante especial para recibir invitados.",
 ["200 ml de jugo de uva", "1 raja de canela", "3 vainas de cardamomo", "1 cucharadita de esencia de vainilla", "4 peras maduras, peladas, sin corazón y partidas por la mitad"],
 ["Ponga el jugo de uva, la raja de canela, las vainas de cardamomo y la esencia de vainilla en una olla grande con 300 ml de agua.", "Caliente suavemente, con cuidado de que no hierva. Esto tardará solo unos minutos. Añada las peras. Tape y cocine a fuego lento de 10 a 12 minutos, o hasta que las peras se ablanden ligeramente.", "Sirva las peras calientes con un poco del líquido de cocción."],
 ["Sirva con yogur griego sin grasa (0 %) para reducir la grasa y las calorías."]),
("الكمثرى المسلوقة بالتوابل",
 "حلوى قليلة السعرات الحرارية ومميزة بما يكفي لاستقبال الضيوف.",
 ["200 مل من عصير العنب", "1 عود قرفة", "3 حبات هيل", "1 ملعقة صغيرة من خلاصة الفانيليا", "4 حبات كمثرى ناضجة، مقشرة ومنزوعة القلب ومقسومة إلى نصفين"],
 ["ضع عصير العنب وعود القرفة وحبات الهيل وخلاصة الفانيليا في قدر كبير مع 300 مل من الماء.", "سخّنها برفق مع الحرص على ألا تغلي. سيستغرق ذلك بضع دقائق فقط. أضف الكمثرى. غطِّ القدر واتركها على نار هادئة برفق من 10 إلى 12 دقيقة أو حتى تلين الكمثرى قليلًا.", "قدّم الكمثرى ساخنة مع قليل من سائل الطهي."],
 ["قدّمها مع الزبادي اليوناني خالي الدسم (0%) لتقليل الدهون والسعرات الحرارية."])))
R.append((7660769,
("Chana chaat (ensalada mixta de legumbres)",
 "Un excelente plato para servir en un bufé.",
 ["1 puñado grande de menta fresca", "½ chile verde, sin semillas", "½ cebolla, picada", "250 g de yogur natural bajo en grasa", "una pizca de chile en polvo", "pimienta negra recién molida", "2 latas de 400 g de garbanzos, escurridos y enjuagados", "1 lata de 560 g de papas nuevas, escurridas y cortadas en cuartos", "1 lata de 220 g de frijoles rojos, escurridos y enjuagados", "1 lata de 220 g de frijoles de ojo negro, escurridos y enjuagados", "1 lata de 198 g de elote (maíz dulce), escurrido", "½ cucharadita de chile en polvo o al gusto", "1 chile verde, finamente picado", "½ cucharadita de chaat masala", "1 cucharadita de jugo de limón", "1 cebolla pequeña, finamente picada", "1 tomate, finamente picado", "1 cucharadita de garam masala en polvo"],
 ["Para el chutney de menta, ponga la menta, el chile y la cebolla en una licuadora o procesador de alimentos y licue hasta obtener un puré, añadiendo un poco de agua si es necesario.", "Incorpore el yogur, sazone bien y añada una pizca de chile en polvo.", "Para el chana chaat, mezcle todos los ingredientes en un tazón grande hasta integrarlos bien. Decore con el garam masala y un poco de chutney de menta."],
 ["El chana chaat también queda muy bien tibio; solo caliente en el microondas unos minutos y sirva con el chutney de menta frío.", "Instrucciones para congelar: Descongele a temperatura ambiente durante dos horas, o caliente en el microondas o en un horno a temperatura moderada."]),
("تشانا تشات (سلطة البقوليات المشكلة)",
 "طبق رائع للتقديم على البوفيه.",
 ["1 حفنة كبيرة من النعناع الطازج", "½ حبة فلفل حار أخضر، منزوعة البذور", "½ بصلة، مفرومة", "250 غرامًا من الزبادي الطبيعي قليل الدسم", "رشة من مسحوق الفلفل الحار", "فلفل أسود مطحون طازجًا", "2 علبة حمص 400 غرام، مصفّاة ومشطوفة", "1 علبة بطاطس صغيرة جديدة 560 غرامًا، مصفّاة ومقطعة أرباعًا", "1 علبة فاصوليا حمراء 220 غرامًا، مصفّاة ومشطوفة", "1 علبة لوبيا (فاصوليا بعين سوداء) 220 غرامًا، مصفّاة ومشطوفة", "1 علبة ذرة حلوة 198 غرامًا، مصفّاة", "½ ملعقة صغيرة من مسحوق الفلفل الحار أو حسب الرغبة", "1 حبة فلفل حار أخضر، مفرومة ناعمًا", "½ ملعقة صغيرة من تشات مسالا", "1 ملعقة صغيرة من عصير الليمون", "1 بصلة صغيرة، مفرومة ناعمًا", "1 حبة طماطم، مفرومة ناعمًا", "1 ملعقة صغيرة من مسحوق غرام مسالا"],
 ["لصلصة النعناع (التشاتني)، ضع النعناع والفلفل الحار والبصل في خلاط أو معالج طعام وامزجها حتى تصبح هريسة، مع إضافة قليل من الماء عند الحاجة.", "أضف الزبادي وقلّب، وتبّل جيدًا وأضف رشة من مسحوق الفلفل الحار.", "للتشانا تشات، اخلط جميع المكونات جيدًا في وعاء كبير. زيّنها بغرام مسالا وقليل من صلصة النعناع."],
 ["يُقدَّم التشانا تشات جيدًا أيضًا وهو دافئ، فقط سخّنه في المايكرويف لبضع دقائق وقدّمه مع صلصة النعناع الباردة.", "تعليمات التجميد: أذبه في درجة حرارة الغرفة لمدة ساعتين، أو سخّنه في المايكرويف أو في فرن معتدل الحرارة."])))
